package br.casasala.painel;
import java.net.*;import java.io.*;import org.json.*;
public final class VoiceBridge{
 public static byte[] call(String base,String token,String path,JSONObject body)throws Exception{URL url=new URL(base.replaceAll("/+$","")+path);if(!url.getProtocol().equals("http")||url.getUserInfo()!=null)throw new Exception("Use HTTP na rede local para a ponte de voz.");if(token.length()<24||token.indexOf('\n')>=0||token.indexOf('\r')>=0)throw new Exception("Importe a chave da ponte de voz.");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(4000);c.setReadTimeout(25000);c.setRequestProperty("Authorization","Bearer "+token);try{if(body!=null){byte[] payload=body.toString().getBytes("UTF-8");c.setRequestMethod("POST");c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);c.setFixedLengthStreamingMode(payload.length);OutputStream out=c.getOutputStream();out.write(payload);out.close();}if(c.getResponseCode()!=200)throw new Exception(c.getResponseCode()==401?"Chave da ponte de voz incorreta.":"Ponte de voz indisponível. Confira se o computador está ligado.");InputStream in=c.getInputStream();ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(data.size()+n>2097152)throw new Exception("Resposta da ponte muito grande.");data.write(b,0,n);}in.close();return data.toByteArray();}finally{c.disconnect();}}
 private VoiceBridge(){}
}
